spark.conf.set("spark.sql.parquet.datetimeRebaseModeInRead", "LEGACY")
spark.conf.set("spark.sql.parquet.int96RebaseModeInRead", "LEGACY")

def resultado(tipo, datos):
    print("VALIDACION_RVI|" + tipo + "|" + json.dumps(
        datos, ensure_ascii=False, default=str
    ), flush=True)

def columna(df, nombre):
    coincidencias = [c for c in df.columns if c.lower() == nombre.lower()]
    if len(coincidencias) != 1:
        raise ValueError("Columna ausente o ambigua: " + nombre)
    return coincidencias[0]

def claves(df):
    campos = {f.name: f.dataType for f in df.schema.fields}
    expresiones = []
    for nombre in llaves:
        real = columna(df, nombre)
        valor = F.col(real)
        if isinstance(campos[real], NumericType):
            valor = valor.cast("decimal(38,0)")
        expresiones.append(valor.cast("string").alias(nombre.upper()))
    return df.select(*expresiones)

def lotes_requeridos(d):
    valores = (
        d.get("lotes_preparacion_silver")
        or d.get("lotes_segmento")
        or [d.get("lote_cargue_id_dataset")]
    )
    return sorted({int(v) for v in valores if v is not None})

pivote = next(
    d for d in p["datasets_extraidos"]
    if str(d.get("tipo_tabla", "")).upper() == "PIVOTE"
)
lotes = lotes_requeridos(pivote)

resultado("CONTEXTO", {
    "periodo": p["periodo_negocio"],
    "execution_id": p.get("execution_id"),
    "lote_ejecucion": p["lote_cargue_id"],
    "lotes_pivote": lotes,
    "filtro": ENTRADA["where"],
    "alcance": "Llaves y disponibilidad; no valida todos los atributos"
})

# Oracle: misma tabla, conexion y filtro publicados para RVI.
conexion = gc.extract_jdbc_conf(
    connection_name="datalake-dev-alfaniif-pre-connection"
)
sql = (
    "SELECT " + ", ".join(llaves)
    + " FROM " + ENTRADA["dbtable"]
    + " WHERE " + ENTRADA["where"]
)
oracle = (
    spark.read.format("jdbc")
    .option("url", conexion.get("fullUrl") or conexion["url"])
    .option("driver", "oracle.jdbc.OracleDriver")
    .option("user", conexion["user"])
    .option("password", conexion["password"])
    .option("dbtable", "(" + sql + ") DIAG_RVI")
    .option("fetchsize", "10000")
    .load()
)
ko = claves(oracle).cache()
total_oracle = ko.count()
resultado("ORACLE", {"filas": total_oracle})

# Bronze: aplicar el mismo filtro y solo los lotes declarados.
bronze = spark.read.parquet(pivote["ruta_dataset_origen"])
lc = columna(bronze, "LOTE_CARGUE_ID")
bronze = bronze.filter(F.col(lc).cast("bigint").isin(lotes))
bronze = bronze.filter(ENTRADA["where"])
kb = claves(bronze).cache()
total_bronze = kb.count()

# exceptAll conserva multiplicidades: no oculta duplicados.
faltan = ko.exceptAll(kb).count()
sobran = kb.exceptAll(ko).count()
resultado("COMPARACION_PIVOTE", {
    "oracle": total_oracle,
    "bronze_lotes_referenciados": total_bronze,
    "llaves_faltantes_en_bronze": faltan,
    "llaves_adicionales_en_bronze": sobran,
    "coinciden_llaves_y_multiplicidades": faltan == 0 and sobran == 0
})
ko.unpersist()
kb.unpersist()

# Todas las tablas: comprobar fisicamente los lotes declarados.
for d in p["datasets_extraidos"]:
    tabla = d["tabla_relativa"]
    requeridos = lotes_requeridos(d)
    for capa, campo in (
        ("BRONZE", "ruta_dataset_origen"),
        ("SILVER", "ruta_dataset_destino")
    ):
        uri = d.get(campo)
        try:
            df = spark.read.parquet(uri)
            lc = columna(df, "LOTE_CARGUE_ID")
            lotes_df = df.select(
                F.col(lc).cast("bigint").alias("_lote")
            )
            filas = (
                lotes_df.filter(F.col("_lote").isin(requeridos))
                .groupBy("_lote").count().collect()
            )
            conteos = {str(r["_lote"]): r["count"] for r in filas}
            maximo = lotes_df.agg(
                F.max("_lote").alias("maximo")
            ).first()["maximo"]

            resultado("TABLA", {
                "tabla": tabla,
                "capa": capa,
                "modo_disponibilidad": d.get("modo_disponibilidad"),
                "filas_declaradas": d.get("total_registros"),
                "lotes_referenciados": requeridos,
                "filas_fisicas_por_lote": conteos,
                "lotes_sin_filas": [
                    x for x in requeridos if str(x) not in conteos
                ],
                "maximo_lote_fisico": maximo
            })
        except Exception as error:
            resultado("ERROR_TABLA", {
                "tabla": tabla, "capa": capa,
                "error": str(error)[:1800]
            })

resultado("FIN", {
    "mensaje": "Diagnostico terminado. Revisar comparacion y errores por tabla."
})
job.commit()
